	@Test
	void certifiedPrimitiveNumericSnapshotsPreserveDatatypeAndLexicalValue() {
		List<Literal> values = List.of(VF.createLiteral((byte) -5), VF.createLiteral((short) 12),
				VF.createLiteral(4), VF.createLiteral(Long.MIN_VALUE), VF.createLiteral(-0.0f),
				VF.createLiteral(Double.POSITIVE_INFINITY), VF.createLiteral(Double.NaN));
		for (Literal value : values) {
			NativeCompiledBindingSetValue descriptor = NativeCompiledBindingSetValue.capture(new ValueConstant(value));
			assertThat(descriptor).as("built-in primitive literal %s", value).isNotNull();
			Value restored = ((ValueConstant) descriptor.expression()).getValue();
			assertThat(restored).isNotSameAs(value).isEqualTo(value);
			assertThat(((Literal) restored).getDatatype()).isEqualTo(value.getDatatype());
			assertThat(restored.stringValue()).isEqualTo(value.stringValue());
		}
	}

